/**
 * Wilson score interval 下界（95% 置信度）
 * 给定观测比例和样本量，返回置信区间下界。
 * 用于进化信号有效性判定——信号强度下界低于阈值则不应触发。
 */
export declare function wilsonCILower(observed: number, n: number, z?: number): number;
/**
 * Welch's t-test（不等方差独立样本 t 检验）
 * 用于比较 before 和 after 两个分数序列是否有显著差异。
 */
export declare function welchTTest(before: number[], after: number[]): {
    significant: boolean;
    pValue: number;
    meanDiff: number;
    tStat: number;
    df: number;
};
